namespace Cosmos.Cst;
public static class Synaptic{public static double Affinity(double[]a,double[]b,double sigma=1){if(sigma<=0||a.Length==0||a.Length!=b.Length)throw new ArgumentException("invalid vectors or sigma");double d2=0;for(int i=0;i<a.Length;i++){double d=a[i]-b[i];d2+=d*d;}return Math.Exp(-d2/(2*sigma*sigma));}public static double Blend(double s,double a,double g){if(g<0||g>1)throw new ArgumentOutOfRangeException(nameof(g));return(1-g)*s+g*a;}public static double[] Step(double[]state,double[]signal,double decay=.92,double gain=1,double dt=1){if(state.Length==0||state.Length!=signal.Length||decay<0||decay>1||dt<0)throw new ArgumentException("invalid state update arguments");double ed=Math.Pow(decay,dt);var o=new double[state.Length];for(int i=0;i<state.Length;i++)o[i]=ed*state[i]+(1-ed)*gain*Math.Tanh(signal[i]);return o;}}
public sealed class SynapticFunction{public double Sigma{get;}public double Gate{get;}public SynapticFunction(double sigma=1,double gate=.5){if(sigma<=0||gate<0||gate>1)throw new ArgumentException("invalid sigma or gate");Sigma=sigma;Gate=gate;}public double Affinity(double[]a,double[]b)=>Synaptic.Affinity(a,b,Sigma);public double Blend(double s,double a)=>Synaptic.Blend(s,a,Gate);public double[] Step(double[]s,double[]u,double d=.92,double k=1,double dt=1)=>Synaptic.Step(s,u,d,k,dt);}
